// --- React Equivalent Pattern ---
import { useQuery } from '@tanstack/react-query';

export function UserList() {
  const { data: users, isLoading } = useQuery({
    queryKey: ['users'],
    queryFn: () => fetch('/api/users').then(res => res.json())
  });

  if (isLoading) return <div>Loading...</div>;

  return (
    <ul>
      {users?.map(u => (
        <li key={u.id}>{u.name}</li>
      ))}
    </ul>
  );
}
```
_Contrasts Angular Injectable service + async pipe with React TanStack Query + JSX mapping._

### 💡 Senior Engine & Architecture Insight
> When migrating an enterprise app from Angular to React, avoid trying to rebuild Angular's DI and RxJS architecture inside React with complex Context wrappers. Embrace idiomatic React: Custom Hooks for logic reuse and TanStack Query for server state.

### 🎯 Probable Interviewer Follow-ups
- **Q: Why doesn't React need a Dependency Injection framework?**
  *A:* Because React functions and Custom Hooks compose naturally via module imports, function arguments, and React Context without requiring runtime container reflection.
- **Q: How do Signals in modern Angular 17+ compare to React State Hooks?**
  *A:* Angular Signals track dependencies automatically at runtime and notify exact DOM nodes directly, whereas React `useState` schedules a whole-component re-render and VDOM diff.
